1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = { itemType: string; amount: number };
9	
10	export type Incident = { cause: string; damages: Damage[] };
11	
12	export type QuoteStep = { op: "quote"; items: Item[] };
13	
14	// `policy` is the zero-based index of the quote step that created the policy.
15	export type ClaimStep = { op: "claim"; policy: number; incident: Incident };
16	
17	export type Step = QuoteStep | ClaimStep;
18	
19	export type Customer = { yearsWithMHPCO: number };
20	
21	export type Scenario = {
22	  customer: Customer;
23	  steps: Step[];
24	};
25	
26	export type QuoteResult = { premium: number };
27	
28	export type ClaimResult = { payout: number; remainingCap: number };
29	
30	export type StepResult = QuoteResult | ClaimResult;
31	
32	export type ScenarioResult = { results: StepResult[] };
33	
34	const BASE_PRICE_BY_TYPE: Record<string, number> = {
35	  sword: 100,
36	  amulet: 60,
37	  staff: 80,
38	  potion: 40,
39	  rune: 25,
40	  moonstone: 25,
41	};
42	
43	// What an item is insured for, as opposed to what it costs to insure.
44	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
45	  sword: 1000,
46	  amulet: 600,
47	  staff: 800,
48	  potion: 400,
49	  rune: 250,
50	  moonstone: 250,
51	};
52	
53	const FIRST_INSURANCE_MULTIPLIER = 1.1;
54	const CONTRACT_FEE = 5;
55	
56	const BUILDING_BLOCK_SIZE = 3;
57	const BUILDING_BLOCK_PRICE = 60;
58	
59	const CURSED_SURCHARGE_RATE = 0.5;
60	const HIGH_ENCHANTMENT_LEVEL = 5;
61	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
62	
63	// Each surcharge adds a percentage of the base price when its condition holds.
64	// Rates add together, so a cursed and highly enchanted item pays 1 + 0.5 + 0.3.
65	const RISK_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
66	  { appliesTo: (item) => item.cursed === true, rate: CURSED_SURCHARGE_RATE },
67	  {
68	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
69	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
70	  },
71	];
72	
73	const totalSurchargeRateFor = (item: Item): number =>
74	  RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).reduce(
75	    (total, surcharge) => total + surcharge.rate,
76	    0,
77	  );
78	
79	// Risk surcharges apply per item, before the contract-level multiplier and fee.
80	const riskAdjustedPriceOfItem = (item: Item): number =>
81	  BASE_PRICE_BY_TYPE[item.type] * (1 + totalSurchargeRateFor(item));
82	
83	const sumOfIndividualPrices = (items: Item[]): number =>
84	  items.reduce((total, item) => total + riskAdjustedPriceOfItem(item), 0);
85	
86	// "Alike" in the price list means same type — material and enchantment do not
87	// affect whether components group into a building block.
88	const groupByType = (items: Item[]): Item[][] => [
89	  ...items
90	    .reduce(
91	      (groups, item) =>
92	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
93	      new Map<string, Item[]>(),
94	    )
95	    .values(),
96	];
97	
98	// Every three alike components form a building block priced at 60 G; the
99	// remainder of the group is priced individually.
100	const priceOfAlikeGroup = (group: Item[]): number => {
101	  const itemsInBlocks = group.length - (group.length % BUILDING_BLOCK_SIZE);
102	
103	  return (
104	    (itemsInBlocks / BUILDING_BLOCK_SIZE) * BUILDING_BLOCK_PRICE +
105	    sumOfIndividualPrices(group.slice(itemsInBlocks))
106	  );
107	};
108	
109	// The basis the premium is charged on: price-list figures plus per-item risk
110	// surcharges, before any contract-level multiplier or fee. Distinct from
111	// coverSumOf, which is what those same items are insured *for*.
112	const premiumBasisOf = (items: Item[]): number =>
113	  groupByType(items).reduce((total, group) => total + priceOfAlikeGroup(group), 0);
114	
115	const LOYALTY_YEARS = 2;
116	const LOYALTY_DISCOUNT_RATE = 0.2;
117	
118	const loyaltyMultiplierFor = (customer: Customer): number =>
119	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? 1 - LOYALTY_DISCOUNT_RATE : 1;
120	
121	const REPEAT_CONTRACT_DISCOUNT_RATE = 0.15;
122	
123	// A first insurance carries an assessment surcharge; every later contract
124	// earns the repeat-customer discount instead.
125	const repeatCustomerMultiplierFor = (precedingContracts: number): number =>
126	  precedingContracts === 0
127	    ? FIRST_INSURANCE_MULTIPLIER
128	    : 1 - REPEAT_CONTRACT_DISCOUNT_RATE;
129	
130	// Customer-dependent factors that scale the whole contract, as opposed to the
131	// per-item risk surcharges already folded into the insured value.
132	const contractMultiplierFor = (
133	  customer: Customer,
134	  precedingContracts: number,
135	): number =>
136	  loyaltyMultiplierFor(customer) * repeatCustomerMultiplierFor(precedingContracts);
137	
138	// Amounts are rounded up, in MHPCO's favor. The product is first snapped to
139	// six decimals so IEEE754 noise (100 × 1.1 = 110.00000000000001) does not
140	// push an exact amount to the next whole G.
141	const roundedUpInMHPCOsFavor = (amount: number): number =>
142	  Math.ceil(Number(amount.toFixed(6)));
143	
144	const resultOfQuoteStep = (
145	  step: QuoteStep,
146	  customer: Customer,
147	  precedingContracts: number,
148	): QuoteResult => ({
149	  premium:
150	    roundedUpInMHPCOsFavor(
151	      premiumBasisOf(step.items) *
152	        contractMultiplierFor(customer, precedingContracts),
153	    ) + CONTRACT_FEE,
154	});
155	
156	const DEDUCTIBLE = 100;
157	const CAP_FACTOR = 2;
158	
159	// What the items are insured for, as opposed to what they cost to insure.
160	const coverSumOf = (items: Item[]): number =>
161	  items.reduce((total, item) => total + INSURANCE_VALUE_BY_TYPE[item.type], 0);
162	
163	// A claim names the quote step that created its policy. Resolving it by
164	// narrowing rather than casting means a mis-aimed index fails here, with the
165	// offending index in hand, instead of silently yielding NaN downstream.
166	const insuredItemsOf = (policyIndex: number, steps: Step[]): Item[] => {
167	  const policy = steps[policyIndex];
168	
169	  if (policy?.op !== "quote") {
170	    throw new Error(`Step ${policyIndex} is not a quote step`);
171	  }
172	
173	  return policy.items;
174	};
175	
176	const totalDamageOf = (incident: Incident): number =>
177	  incident.damages.reduce((total, { amount }) => total + amount, 0);
178	
179	const resultOfClaimStep = (step: ClaimStep, steps: Step[]): ClaimResult => {
180	  const cap = CAP_FACTOR * coverSumOf(insuredItemsOf(step.policy, steps));
181	  const payout = Math.max(0, totalDamageOf(step.incident) - DEDUCTIBLE);
182	
183	  return { payout, remainingCap: cap - payout };
184	};
185	
186	export const runScenario = (scenario: Scenario): ScenarioResult => ({
187	  results: scenario.steps.map((step, index) =>
188	    step.op === "quote"
189	      ? resultOfQuoteStep(step, scenario.customer, index)
190	      : resultOfClaimStep(step, scenario.steps),
191	  ),
192	});
